// Specification: https://leetcode.com/problems/brick-wall/description/
function solve(wall) {
  const counts = new Map();
  for (const row of wall) {
    let position = 0;
    for (let i = 0; i < row.length - 1; i++) {
      position += row[i];
      counts.set(position, (counts.get(position) || 0) + 1);
    }
  }
