def solve(price: list[int], special: list[list[int]], needs: list[int]) -> int:
    memo = {}

    def dfs(current):
        key = tuple(current)
        if key in memo:
            return memo[key]
        best = sum(current[i] * price[i] for i in range(len(current)))
        for offer in special:
            nxt = current[:]
            valid = True
            for i in range(len(current)):
                nxt[i] -= offer[i]
                if nxt[i] < 0:
